# Exact machine-local files generated by Android Studio and intentionally kept
# outside the protected game-source inventory. Keep this list narrow: unknown
# files under .idea remain subject to the normal manifest gate.
$script:SightlineLocalAndroidStudioMetadata = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
foreach ($path in @(
  'AndroidProject/.idea/.gitignore',
  'AndroidProject/.idea/.name',
  'AndroidProject/.idea/AndroidProjectSystem.xml',
  'AndroidProject/.idea/caches/deviceStreaming.xml',
  'AndroidProject/.idea/compiler.xml',
  'AndroidProject/.idea/deploymentTargetSelector.xml',
  'AndroidProject/.idea/gradle.xml',
  'AndroidProject/.idea/migrations.xml',
  'AndroidProject/.idea/misc.xml',
  'AndroidProject/.idea/workspace.xml',
  'AndroidProject/local.properties'
)) { [void]$script:SightlineLocalAndroidStudioMetadata.Add($path) }

function Test-SightlineLocalAndroidStudioMetadata([string]$RelativePath) {
  if ($null -eq $RelativePath) { return $false }
  return $script:SightlineLocalAndroidStudioMetadata.Contains($RelativePath.Replace('\','/'))
}
